const Input = ({ label, required, hint, error, ...props }) => {
  const id = useId(), describedBy = error ? `${id}-error` : hint ? `${id}-hint` : undefined
  return <label className="field" htmlFor={id}><span>{label}{required && <b aria-hidden="true">*</b>}</span><input id={id} aria-required={required||undefined} aria-invalid={Boolean(error)||undefined} aria-describedby={describedBy} {...props}/>{error?<small className="field-error" id={`${id}-error`}>{error}</small>:hint&&<small id={`${id}-hint`}>{hint}</small>}</label>
}
const Select = ({ label, required, children, error, ...props }) => {
  const id = useId()
  return <label className="field" htmlFor={id}><span>{label}{required && <b aria-hidden="true">*</b>}</span><select id={id} aria-required={required||undefined} aria-invalid={Boolean(error)||undefined} aria-describedby={error?`${id}-error`:undefined} {...props}><option value="">Selecione</option>{children}</select>{error&&<small className="field-error" id={`${id}-error`}>{error}</small>}</label>
}

function Choice({ name, value, checked, onChange, children }) {
  return <label className={`choice ${checked ? 'selected' : ''}`}><input type="radio" name={name} value={value} checked={checked} onChange={onChange}/><i>{checked && <Check size={12}/>}</i>{children}</label>
}

function FormStep({ step, data, setData, errors }) {
  const set = (key) => (e) => setData({ ...data, [key]: e.target.value })
  const radio = (key) => (e) => setData({ ...data, [key]: e.target.value })
  const toggle = (key, value) => setData({ ...data, [key]: data[key].includes(value) ? data[key].filter(x => x !== value) : [...data[key], value] })
  const updateItem = (key, index, field, value) => setData({ ...data, [key]: data[key].map((item, i) => i === index ? { ...item, [field]: value } : item) })
  const addItem = (key, item, max) => data[key].length < max && setData({ ...data, [key]: [...data[key], item] })
  const removeItem = (key, index) => setData({ ...data, [key]: data[key].filter((_, i) => i !== index) })
  const updateTextItem = (key, index, value) => setData({ ...data, [key]: data[key].map((item, i) => i === index ? value : item) })
  if (step === 1) return <>
    <SectionTitle icon={<UserRound/>} title="Identificação" subtitle="Informe seus dados pessoais conforme os documentos oficiais." />
    <div className="form-grid"><Input label="Nome completo" required placeholder="Digite seu nome completo" autoComplete="name" value={data.nome} onChange={set('nome')} className={errors.nome?'invalid':''} error={errors.nome}/><Input label="CPF" required hint={!errors.cpf?'Digite somente os 11 números.':undefined} placeholder="00000000000" inputMode="numeric" autoComplete="off" maxLength="11" value={data.cpf} onChange={e=>setData({...data,cpf:onlyDigits(e.target.value).slice(0,11)})} className={errors.cpf?'invalid':''} error={errors.cpf}/><Input label="Data de nascimento" required type="date" autoComplete="bday" value={data.nascimento} onChange={set('nascimento')} className={errors.nascimento?'invalid':''} error={errors.nascimento}/><Input label="E-mail" required type="email" autoComplete="email" placeholder="voce@exemplo.com" value={data.email} onChange={set('email')} className={errors.email?'invalid':''} error={errors.email}/><Input label="Telefone / WhatsApp" required type="tel" inputMode="tel" autoComplete="tel" placeholder="61999999999" value={data.telefone} onChange={set('telefone')} className={errors.telefone?'invalid':''} error={errors.telefone}/></div>
    <div className="sub-card filiation-card"><div className="sub-card-title">Filiação</div><div className="filiation-row"><Input label="Nome completo da filiação 1" placeholder="Digite o nome completo" disabled={data.filiacao1NaoDeclarada} value={data.filiacao1} onChange={set('filiacao1')}/><MiniCheck label="Não declarado" checked={data.filiacao1NaoDeclarada} onChange={checked=>setData({...data,filiacao1NaoDeclarada:checked,filiacao1:checked?'':data.filiacao1})}/></div><div className="filiation-row"><Input label="Nome completo da filiação 2" placeholder="Digite o nome completo" disabled={data.filiacao2NaoDeclarada} value={data.filiacao2} onChange={set('filiacao2')}/><MiniCheck label="Não declarado" checked={data.filiacao2NaoDeclarada} onChange={checked=>setData({...data,filiacao2NaoDeclarada:checked,filiacao2:checked?'':data.filiacao2})}/></div></div>
    <FieldGroup label="Sexo" required><Choice name="sexo" value="Masculino" checked={data.sexo==='Masculino'} onChange={radio('sexo')}>Masculino</Choice><Choice name="sexo" value="Feminino" checked={data.sexo==='Feminino'} onChange={radio('sexo')}>Feminino</Choice></FieldGroup>
    <FieldGroup label="Cor/raça" required>{['Branca','Preta','Parda','Amarela','Indígena','Não declarada'].map(v=><Choice key={v} name="raca" value={v} checked={data.raca===v} onChange={radio('raca')}>{v}</Choice>)}</FieldGroup>
    {data.raca==='Indígena' && <div className="conditional-card"><Input label="Nome do povo / tribo indígena" required placeholder="Ex.: Guarani, Yanomami, Tikuna..." value={data.povoIndigena} onChange={set('povoIndigena')} className={errors.povoIndigena?'invalid':''} hint="Informe o povo indígena ao qual você pertence."/></div>}
    <div className="form-grid"><Select label="Nacionalidade" required value={data.nacionalidade} onChange={set('nacionalidade')}><option>Brasileira</option><option>Brasileira — nascido no exterior ou naturalizado</option><option>Estrangeira</option></Select><Input label="Município de nascimento" placeholder="Ex.: Brasília" value={data.cidadeNascimento} onChange={set('cidadeNascimento')}/><Input label="UF de nascimento" maxLength="2" placeholder="DF" value={data.ufNascimento} onChange={set('ufNascimento')}/></div>
    <FieldGroup label="Possui deficiência, transtorno do espectro autista ou altas habilidades?" required><Choice name="deficiencia" value="Não" checked={data.deficiencia==='Não'} onChange={radio('deficiencia')}>Não</Choice><Choice name="deficiencia" value="Sim" checked={data.deficiencia==='Sim'} onChange={radio('deficiencia')}>Sim</Choice></FieldGroup>
    {data.deficiencia==='Sim' && <CheckboxGroup values={['Baixa visão','Cegueira','Deficiência auditiva','Surdez','Surdocegueira','Deficiência física','Deficiência intelectual','Deficiência múltipla','Transtorno do espectro autista','Altas habilidades ou superdotação']} selected={data.tipoDeficiencia} onToggle={v=>toggle('tipoDeficiencia',v)}/>}
  </>
  if (step === 2) return <>
    <SectionTitle icon={<FileText/>} title="Área residencial" subtitle="Informe o endereço onde você reside atualmente." />
    <div className="form-grid"><Input label="CEP" required inputMode="numeric" placeholder="00000000" value={data.cep} onChange={set('cep')} className={errors.cep?'invalid':''} error={errors.cep}/><Input label="Município" required placeholder="Digite sua cidade" value={data.cidade} onChange={set('cidade')} className={errors.cidade?'invalid':''} error={errors.cidade}/><Input label="UF" required maxLength="2" placeholder="DF" value={data.uf} onChange={e=>setData({...data,uf:e.target.value.toUpperCase()})} className={errors.uf?'invalid':''} error={errors.uf}/></div>
    <FieldGroup label="Localização / zona de residência" required><Choice name="zona" value="Urbana" checked={data.zona==='Urbana'} onChange={radio('zona')}>Urbana</Choice><Choice name="zona" value="Rural" checked={data.zona==='Rural'} onChange={radio('zona')}>Rural</Choice></FieldGroup>
    <FieldGroup label="Localização diferenciada"><div className="choice-grid">{['Não está em área diferenciada','Área de assentamento','Comunidade quilombola','Terra indígena','Comunidade tradicional'].map(v=><Choice key={v} name="localizacao" value={v} checked={data.localizacao===v} onChange={radio('localizacao')}>{v}</Choice>)}</div></FieldGroup>
    <div className="info-box"><ShieldCheck/><div><b>Seus dados estão seguros</b><span>As informações de endereço são utilizadas exclusivamente para fins de planejamento educacional.</span></div></div>
  </>
  if (step === 3) return <>
    <SectionTitle icon={<GraduationCap/>} title="Escolaridade e formação" subtitle="Conte-nos sobre sua formação acadêmica e cursos complementares." />
    <Select label="Maior nível de escolaridade concluído" required value={data.escolaridade} onChange={set('escolaridade')} className={errors.escolaridade?'invalid':''}><option>Não concluiu o ensino fundamental</option><option>Ensino fundamental</option><option>Ensino médio</option><option>Educação superior</option></Select>
    <div className="repeater-section"><div className="repeater-heading"><div><b>Formação / complementação pedagógica</b><span>Adicione todas as formações pedagógicas concluídas.</span></div>{data.formacoesPedagogicas.length<6&&<button type="button" className="add-button" onClick={()=>addItem('formacoesPedagogicas',{curso:'',conclusao:''},6)}><Plus size={16}/> Adicionar formação</button>}</div>{data.formacoesPedagogicas.map((item,index)=><div className="sub-card" key={index}><div className="sub-card-title">Formação pedagógica {index+1} <span>opcional</span>{index>0&&<button className="remove-button" type="button" onClick={()=>removeItem('formacoesPedagogicas',index)}><Trash2 size={14}/> Remover</button>}</div><div className="form-grid"><Input label="Curso / área da formação" placeholder="Ex.: Complementação pedagógica em Matemática" value={item.curso} onChange={e=>updateItem('formacoesPedagogicas',index,'curso',e.target.value)}/><Input label="Ano de conclusão" type="number" min="1950" max="2030" placeholder="2024" value={item.conclusao} onChange={e=>updateItem('formacoesPedagogicas',index,'conclusao',e.target.value)}/></div></div>)}</div>
    {data.escolaridade==='Educação superior' && <div className="repeater-section"><div className="repeater-heading"><div><b>Cursos superiores</b><span>Você pode informar até 3 formações.</span></div>{data.cursosSuperiores.length<3&&<button type="button" className="add-button" onClick={()=>addItem('cursosSuperiores',{curso:'',grau:'',instituicao:'',tipoInstituicao:'',conclusao:''},3)}><Plus size={16}/> Adicionar curso superior</button>}</div>{data.cursosSuperiores.map((item,index)=><div className="sub-card" key={index}><div className="sub-card-title">Curso superior {index+1}{index>0&&<button className="remove-button" type="button" onClick={()=>removeItem('cursosSuperiores',index)}><Trash2 size={14}/> Remover</button>}</div><div className="form-grid"><Input label="Nome do curso" required={index===0} placeholder="Ex.: Pedagogia" value={item.curso} onChange={e=>updateItem('cursosSuperiores',index,'curso',e.target.value)}/><Select label="Nível / grau acadêmico" value={item.grau} onChange={e=>updateItem('cursosSuperiores',index,'grau',e.target.value)}><option>Licenciatura</option><option>Bacharelado</option><option>Tecnológico</option><option>Sequencial</option></Select><Input label="Instituição de ensino" placeholder="Nome da instituição" value={item.instituicao} onChange={e=>updateItem('cursosSuperiores',index,'instituicao',e.target.value)}/><Select label="Tipo de instituição" value={item.tipoInstituicao} onChange={e=>updateItem('cursosSuperiores',index,'tipoInstituicao',e.target.value)}><option>Pública</option><option>Privada</option></Select><Input label="Ano de conclusão" type="number" min="1950" max="2030" placeholder="2020" value={item.conclusao} onChange={e=>updateItem('cursosSuperiores',index,'conclusao',e.target.value)}/></div></div>)}</div>}
    <div className="repeater-section"><div className="repeater-heading"><div><b>Pós-graduações</b><span>Especialização, mestrado ou doutorado — até 6 formações.</span></div>{data.posGraduacoes.length<6&&<button type="button" className="add-button" onClick={()=>addItem('posGraduacoes',{curso:'',nivel:'',conclusao:''},6)}><Plus size={16}/> Adicionar pós-graduação</button>}</div>{data.posGraduacoes.map((item,index)=><div className="sub-card" key={index}><div className="sub-card-title">Pós-graduação {index+1} <span>opcional</span>{index>0&&<button className="remove-button" type="button" onClick={()=>removeItem('posGraduacoes',index)}><Trash2 size={14}/> Remover</button>}</div><div className="form-grid"><Input label="Nome do curso / área" placeholder="Ex.: Psicopedagogia" value={item.curso} onChange={e=>updateItem('posGraduacoes',index,'curso',e.target.value)}/><Select label="Nível" value={item.nivel} onChange={e=>updateItem('posGraduacoes',index,'nivel',e.target.value)}><option>Especialização</option><option>Mestrado</option><option>Doutorado</option></Select><Input label="Ano de conclusão" type="number" min="1950" max="2030" placeholder="2024" value={item.conclusao} onChange={e=>updateItem('posGraduacoes',index,'conclusao',e.target.value)}/></div></div>)}</div>
    <FieldGroup label="Cursos de formação continuada (mínimo de 80 horas)" hint="Selecione todos que se aplicam."><CheckboxGroup values={['Creche (0 a 3 anos)','Pré-escola (4 e 5 anos)','Alfabetização','Anos iniciais do ensino fundamental','Anos finais do ensino fundamental','Ensino médio','Educação de jovens e adultos','Educação especial','Educação indígena','Educação do campo','Educação ambiental','Educação em direitos humanos','Educação bilíngue de surdos','Tecnologia da Informação e Comunicação (TIC)','Educação integral em tempo integral','Gênero e diversidade sexual','Direitos da criança e do adolescente','Relações étnico-raciais e história e cultura afro-brasileira e africana','Gestão escolar','Outros','Nenhum']} selected={data.cursos} onToggle={v=>toggle('cursos',v)}/></FieldGroup>
    <div className="repeater-section custom-courses"><div className="repeater-heading"><div><b>Outros cursos específicos</b><span>Adicione outros cursos de formação continuada.</span></div><button type="button" className="add-button" onClick={()=>addItem('outrosCursos','',10)}><Plus size={16}/> Adicionar outro curso</button></div>{data.outrosCursos.map((curso,index)=><div className="inline-repeater" key={index}><Input label={`Outro curso ${index+1}`} placeholder="Digite o nome do curso" value={curso} onChange={e=>updateTextItem('outrosCursos',index,e.target.value)}/>{data.outrosCursos.length>1&&<button className="icon-remove" type="button" title="Remover curso" onClick={()=>removeItem('outrosCursos',index)}><Trash2 size={16}/></button>}</div>)}</div>
  </>
  return <>
    <SectionTitle icon={<BookOpen/>} title="Atuação profissional" subtitle="Informe sua função, carga horária e vínculo atual." />
    <FieldGroup label="Função que exerce" required><div className="role-grid">{['Docente','Auxiliar/assistente educacional','Profissional/monitor(a) de atividade complementar','Docente titular — coordenador(a) de tutoria EaD','Docente tutor(a) — auxiliar EaD','Instrutor(a) de educação profissional','Tradutor(a) e intérprete de Libras','Guia-intérprete','Profissional de apoio escolar','Cuidador(a)','Psicopedagogo(a)'].map(v=><Choice key={v} name="funcao" value={v} checked={data.funcao===v} onChange={radio('funcao')}>{v}</Choice>)}</div></FieldGroup>
    <FieldGroup label="Carga horária semanal" required>{['20h','40h'].map(v=><Choice key={v} name="carga" value={v} checked={data.carga===v} onChange={radio('carga')}>{v}</Choice>)}</FieldGroup>
    <FieldGroup label="Situação funcional / tipo de vínculo" required><div className="choice-grid">{['Concursado/efetivo/estável','Contrato temporário','Contrato terceirizado','Contrato CLT','Bolsista'].map(v=><Choice key={v} name="vinculo" value={v} checked={data.vinculo===v} onChange={radio('vinculo')}>{v}</Choice>)}</div></FieldGroup>
    <div className="sub-card pathway-card"><div className="sub-card-title">Itinerário formativo de aprofundamento (IFA)</div><FieldGroup label="O profissional escolar leciona no IFA?" required><Choice name="ifa" value="Sim" checked={data.ifa==='Sim'} onChange={radio('ifa')}>Sim</Choice><Choice name="ifa" value="Não" checked={data.ifa==='Não'} onChange={radio('ifa')}>Não</Choice></FieldGroup>{data.ifa==='Sim'&&<Input label="Área do itinerário formativo" required placeholder="Ex.: Linguagens e suas tecnologias" value={data.areaIfa} onChange={set('areaIfa')} className={errors.areaIfa?'invalid':''}/>}</div>
    <div className="sub-card pathway-card"><div className="sub-card-title">Itinerário de formação técnica e profissional (IFTP)</div><FieldGroup label="O profissional escolar leciona no IFTP?" required><Choice name="iftp" value="Sim" checked={data.iftp==='Sim'} onChange={radio('iftp')}>Sim</Choice><Choice name="iftp" value="Não" checked={data.iftp==='Não'} onChange={radio('iftp')}>Não</Choice></FieldGroup>{data.iftp==='Sim'&&<Input label="Área da formação técnica e profissional" required placeholder="Informe a área do IFTP" value={data.areaIftp} onChange={set('areaIftp')} className={errors.areaIftp?'invalid':''}/>}</div>
    <label className="field"><span>Observações <small>opcional</small></span><textarea placeholder="Caso necessário, acrescente alguma informação..." value={data.observacoes} onChange={set('observacoes')}/></label>
    <label className={`consent ${errors.consentimento?'consent-error':''}`}><input type="checkbox" checked={data.consentimento} onChange={e=>setData({...data,consentimento:e.target.checked})}/><i>{data.consentimento && <Check size={13}/>}</i><span>Declaro que as informações fornecidas são verdadeiras e autorizo seu uso para fins de planejamento e gestão educacional, conforme a LGPD.</span></label>
  </>
}

function SectionTitle({ icon, title, subtitle }) { return <div className="section-title"><div>{icon}</div><span><h2>{title}</h2><p>{subtitle}</p></span></div> }
function FieldGroup({ label, required, hint, children }) { return <fieldset className="field-group"><legend className="field-label">{label}{required&&<b aria-hidden="true">*</b>}{hint&&<small>{hint}</small>}</legend><div className="choices">{children}</div></fieldset> }
function CheckboxGroup({ values, selected, onToggle }) { return <div className="checkbox-grid">{values.map(v=><label className={`check-choice ${selected.includes(v)?'selected':''}`} key={v}><input type="checkbox" checked={selected.includes(v)} onChange={()=>onToggle(v)}/><i aria-hidden="true">{selected.includes(v)&&<Check size={12}/>}</i>{v}</label>)}</div> }
function MiniCheck({ label, checked, onChange }) { return <label className="mini-check"><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><i aria-hidden="true">{checked&&<Check size={12}/>}</i>{label}</label> }

function Registration({ onHome, onAdmin, onComplete }) {
  const formRef = useRef(null)
  const [step, setStep] = useState(1), [data, setData] = useState(blank), [errors, setErrors] = useState({}), [submitError,setSubmitError]=useState(''), [submitting,setSubmitting]=useState(false)
  const required = {1:['nome','cpf','nascimento','email','telefone','sexo','raca'],2:['cep','cidade','uf','zona'],3:['escolaridade'],4:['funcao','carga','vinculo','consentimento']}
  const advance = async () => {
    const e = {}; required[step].forEach(k=>{if(!data[k])e[k]='Campo obrigatório.'})
    if(step===1&&data.cpf&&!isValidCpf(data.cpf))e.cpf='CPF inválido. Digite os 11 números.'
    if(step===1&&data.email&&!isValidEmail(data.email))e.email='Informe um e-mail válido.'
    if(step===1&&data.telefone&&!isValidPhone(data.telefone))e.telefone='Informe um celular válido com DDD.'
    if(step===1&&data.nascimento&&(Number.isNaN(Date.parse(data.nascimento))||new Date(data.nascimento)>=new Date()))e.nascimento='Informe uma data de nascimento válida.'
    if(step===1&&data.raca==='Indígena'&&!data.povoIndigena.trim())e.povoIndigena='Campo obrigatório para pessoa indígena.'
    if(step===2&&data.cep&&!isValidCep(data.cep))e.cep='Informe os 8 números do CEP.'
    if(step===2&&data.uf&&!/^[A-Za-z]{2}$/.test(data.uf))e.uf='Informe uma UF válida.'
    if(step===3&&data.escolaridade==='Educação superior'&&!data.cursosSuperiores[0]?.curso.trim())e.cursoSuperior='Informe ao menos um curso superior.'
    if(step===4&&data.ifa==='Sim'&&!data.areaIfa.trim())e.areaIfa='Campo obrigatório.'
    if(step===4&&data.iftp==='Sim'&&!data.areaIftp.trim())e.areaIftp='Campo obrigatório.'
    setErrors(e)
    if(Object.keys(e).length) { setTimeout(()=>formRef.current?.querySelector('[aria-invalid="true"], .invalid, .consent-error')?.focus(),0); return }
    window.scrollTo({top:0,behavior:'smooth'})
    if(step<4) setStep(step+1); else {setSubmitting(true);setSubmitError('');try{await onComplete(data)}catch(error){setSubmitError(error.message)}finally{setSubmitting(false)}}
  }
  return <div className="form-page">
    <PublicHeader onAdmin={onAdmin} onHome={onHome}/>
    <div className="form-intro"><button onClick={step===1?onHome:()=>setStep(step-1)}><ArrowLeft size={17}/> {step===1?'Voltar ao início':'Etapa anterior'}</button><div><span>CADASTRO PROFISSIONAL</span><h1>Conte-nos um pouco sobre você</h1><p>Preencha os campos abaixo. Os itens marcados com * são obrigatórios.</p></div></div>
    <div className="stepper">{steps.map((s,i)=><div className={`step ${step===s.n?'active':''} ${step>s.n?'done':''}`} key={s.n}><div>{step>s.n?<Check size={16}/>:s.n}</div><span><b>{s.title}</b><small>Etapa {s.n} de 4</small></span>{i<3&&<i/>}</div>)}</div>
    <main className="form-card" ref={formRef}><FormStep step={step} data={data} setData={setData} errors={errors}/>{Object.keys(errors).length>0&&<div className="error-message" role="alert">Revise os campos destacados antes de continuar.</div>}{submitError&&<div className="error-message" role="alert">{submitError}</div>}<div className="form-actions"><button className="back-button" disabled={step===1||submitting} onClick={()=>setStep(step-1)}><ArrowLeft size={18}/> Voltar</button><button className="primary-button" disabled={submitting} onClick={advance}>{submitting?'Enviando...':step===4?'Enviar cadastro':'Continuar'} {step===4?<CheckCircle2 size={18}/>:<ArrowRight size={18}/>}</button></div></main>
    <div className="form-security"><ShieldCheck size={16}/> Ambiente seguro • Seus dados são protegidos pela LGPD</div>
  </div>
}

function Success({ record, onHome }) { return <div className="success-page"><Logo/><main className="success-card"><div className="success-icon"><Check size={38}/></div><span>CADASTRO ENVIADO</span><h1>Tudo certo, {record.nome.split(' ')[0]}!</h1><p>Recebemos suas informações. Seu cadastro será analisado pela equipe responsável.</p><div className="protocol"><span>Seu número de protocolo</span><div><b>{record.id}</b><button onClick={()=>navigator.clipboard?.writeText(record.id)} title="Copiar"><Copy size={18}/></button></div><small>Guarde este número para consultas futuras.</small></div><button className="primary-button full" onClick={onHome}>Voltar à página inicial</button></main><footer>© 2026 Conecta NAPNE • Seus dados estão protegidos.</footer></div> }

function AdminLogin({ onLogin, onBack }) {
  const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[show,setShow]=useState(false),[error,setError]=useState(false)
  const passwordId=useId()
  const submit=async e=>{e.preventDefault();setError(false);try{const response=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});if(!response.ok)throw new Error();onLogin()}catch{setError(true)}}
  return <div className="login-page"><section className="login-brand"><Logo light/><div><span className="eyebrow light"><span></span> GESTÃO EDUCACIONAL</span><h1>Informação que<br/>transforma a <em>educação.</em></h1><p>Gerencie os cadastros dos profissionais que tornam a educação mais inclusiva todos os dias.</p></div><small>© 2026 Conecta NAPNE</small></section><section className="login-form-wrap"><button className="login-back" onClick={onBack}><ArrowLeft size={17}/> Voltar para o cadastro</button><form className="login-form" onSubmit={submit}><div className="login-shield"><ShieldCheck/></div><h2>Bem-vindo de volta</h2><p>Acesse o painel administrativo</p><Input label="E-mail" type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="seu@email.com"/><div className="field"><label htmlFor={passwordId}>Senha</label><div className="password-input"><input id={passwordId} type={show?'text':'password'} autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Digite sua senha"/><button type="button" aria-label={show?'Ocultar senha':'Mostrar senha'} onClick={()=>setShow(!show)}>{show?<EyeOff/>:<Eye/>}</button></div></div>{error&&<div className="login-error" role="alert">E-mail ou senha incorretos.</div>}<button className="primary-button full" type="submit">Entrar no painel <ArrowRight size={18}/></button></form></section></div>
}

const studentBlank = {
  codigoEscola:'', identificacaoInep:'', cpf:'', nome:'', nascimento:'', filiacao1:'', filiacao1NaoDeclarada:false, filiacao2:'', filiacao2NaoDeclarada:false,
  sexo:'', raca:'', povoIndigena:'', nacionalidade:'Brasileira', paisNacionalidade:'Brasil', ufNascimento:'', municipioNascimento:'', deficiencia:'Não', tiposDeficiencia:[],
  transtornoAprendizagem:'Não', tiposTranstorno:[], recursos:'Não', tiposRecursos:[], certidao:'', paisResidencia:'Brasil', cep:'', ufResidencia:'', municipioResidencia:'', zona:'', localizacao:'Não está em área de localização diferenciada',
  turma:'', etapa:'', etapaAno:'', cargaIntegralizada:'', tiposAee:[], atendimento:'Não recebe', transporte:'Não utiliza', responsavelTransporte:'', veiculos:[]
}

const disabilityOptions=['Baixa visão','Cegueira','Visão monocular','Deficiência auditiva','Surdez','Surdocegueira','Deficiência física','Deficiência intelectual','Deficiência múltipla','Transtorno do espectro autista','Altas habilidades ou superdotação']
const disorderOptions=['Discalculia ou outro transtorno da matemática e raciocínio lógico','Disgrafia, Disortografia ou outro transtorno da escrita e ortografia','Dislalia ou outro transtorno da linguagem e comunicação','Dislexia','Transtorno do Déficit de Atenção com Hiperatividade (TDAH)','Transtorno do Processamento Auditivo Central (TPAC)']
const resourceOptions=['Auxílio ledor','Auxílio transcrição','Guia-intérprete','Tradutor-intérprete de Libras','Leitura labial','Material didático em Braille','Prova em Braille','Prova ampliada (Fonte 18)','Prova superampliada (Fonte 24)','CD com áudio para deficiente visual','Prova de Língua Portuguesa como Segunda Língua para surdos e deficientes auditivos','Prova em Vídeo Libras','Tempo adicional']
const aeeOptions=['Desenvolvimento de funções cognitivas','Desenvolvimento de vida autônoma','Enriquecimento curricular','Ensino da informática acessível','Ensino de Libras','Ensino de Língua Portuguesa como Segunda Língua','Ensino das técnicas de cálculo no Soroban','Ensino de Sistema Braille','Ensino de técnicas para orientação e mobilidade','Ensino do uso da Comunicação Alternativa e Aumentativa (CAA)','Ensino dos recursos ópticos e não ópticos']
const vehicleOptions=['Bicicleta','Tração animal','Outro tipo de veículo rodoviário','Vans/Kombis','Micro-ônibus','Ônibus','Aquaviário — até 5 alunos','Aquaviário — entre 5 e 15 alunos','Aquaviário — entre 15 e 35 alunos','Aquaviário — acima de 35 alunos']

function StudentQuestionnaire({ onSave }) {
  const [data,setData]=useState(studentBlank),[step,setStep]=useState(1),[errors,setErrors]=useState({}),[message,setMessage]=useState(''),[saving,setSaving]=useState(false)
  const set=key=>e=>setData({...data,[key]:e.target.value}), radio=key=>e=>setData({...data,[key]:e.target.value})
  const toggle=(key,value)=>setData({...data,[key]:data[key].includes(value)?data[key].filter(item=>item!==value):[...data[key],value]})
  const next=async()=>{
    const e={}
    if(step===1){['codigoEscola','nome','nascimento','sexo','raca','nacionalidade'].forEach(k=>{if(!data[k])e[k]='Campo obrigatório.'});if(data.cpf&&!isValidCpf(data.cpf))e.cpf='CPF inválido.';if(data.nascimento&&(Number.isNaN(Date.parse(data.nascimento))||new Date(data.nascimento)>=new Date()))e.nascimento='Informe uma data de nascimento válida.';if(data.raca==='Indígena'&&!data.povoIndigena)e.povoIndigena='Informe o código do povo indígena.';if(data.nacionalidade==='Estrangeira'&&!data.paisNacionalidade)e.paisNacionalidade='Campo obrigatório.'}
    if(step===2){['paisResidencia','ufResidencia','municipioResidencia','zona'].forEach(k=>{if(!data[k])e[k]='Campo obrigatório.'});if(data.cep&&!isValidCep(data.cep))e.cep='Informe os 8 números do CEP.';if(data.deficiencia==='Sim'&&!data.tiposDeficiencia.length)e.tiposDeficiencia='Selecione ao menos uma opção.';if(data.transtornoAprendizagem==='Sim'&&!data.tiposTranstorno.length)e.tiposTranstorno='Selecione ao menos uma opção.';if(data.recursos==='Sim'&&!data.tiposRecursos.length)e.tiposRecursos='Selecione ao menos um recurso.'}
    if(step===3){['turma','etapa'].forEach(k=>{if(!data[k])e[k]='Campo obrigatório.'});if(data.transporte==='Utiliza'&&!data.responsavelTransporte)e.responsavelTransporte='Campo obrigatório.';if(data.transporte==='Utiliza'&&!data.veiculos.length)e.veiculos='Selecione ao menos um veículo.'}
    setErrors(e);if(Object.keys(e).length)return
    if(step<3){setStep(step+1);window.scrollTo({top:0,behavior:'smooth'});return}
    setSaving(true);setMessage('');try{const student=await onSave(data);setMessage(`Aluno cadastrado com sucesso. Protocolo ${student.id}.`);setData(studentBlank);setStep(1)}catch(error){setMessage(error.message)}finally{setSaving(false)}
  }
  return <section className="student-form" aria-labelledby="student-title"><div className="student-form-heading"><div><span>QUESTIONÁRIO DO ALUNO • CENSO ESCOLAR 2026</span><h2 id="student-title">Cadastrar aluno(a)</h2><p>Preenchimento interno pela equipe do NAPNE. Etapa {step} de 3.</p></div><div className="mini-progress" aria-label={`Etapa ${step} de 3`}>{[1,2,3].map(n=><i key={n} className={n<=step?'active':''}>{n}</i>)}</div></div>
    {step===1&&<><SectionTitle icon={<UserRound/>} title="Identificação" subtitle="Dados de identificação do questionário do Censo Escolar."/><div className="form-grid"><Input label="Código da escola" required value={data.codigoEscola} onChange={set('codigoEscola')} error={errors.codigoEscola}/><Input label="Identificação única (Inep)" value={data.identificacaoInep} onChange={set('identificacaoInep')}/><Input label="CPF (somente números)" inputMode="numeric" maxLength="11" value={data.cpf} onChange={e=>setData({...data,cpf:onlyDigits(e.target.value).slice(0,11)})} error={errors.cpf}/><Input label="Nome completo" required value={data.nome} onChange={set('nome')} error={errors.nome}/><Input label="Data de nascimento" required type="date" value={data.nascimento} onChange={set('nascimento')} error={errors.nascimento}/></div><div className="sub-card filiation-card"><div className="sub-card-title">Filiação</div><div className="filiation-row"><Input label="Nome completo da filiação 1" disabled={data.filiacao1NaoDeclarada} value={data.filiacao1} onChange={set('filiacao1')}/><MiniCheck label="Não declarado" checked={data.filiacao1NaoDeclarada} onChange={v=>setData({...data,filiacao1NaoDeclarada:v,filiacao1:v?'':data.filiacao1})}/></div><div className="filiation-row"><Input label="Nome completo da filiação 2" disabled={data.filiacao2NaoDeclarada} value={data.filiacao2} onChange={set('filiacao2')}/><MiniCheck label="Não declarado" checked={data.filiacao2NaoDeclarada} onChange={v=>setData({...data,filiacao2NaoDeclarada:v,filiacao2:v?'':data.filiacao2})}/></div></div><FieldGroup label="Sexo" required><Choice name="aluno-sexo" value="Masculino" checked={data.sexo==='Masculino'} onChange={radio('sexo')}>Masculino</Choice><Choice name="aluno-sexo" value="Feminino" checked={data.sexo==='Feminino'} onChange={radio('sexo')}>Feminino</Choice></FieldGroup><FieldGroup label="Cor/raça" required>{['Branca','Preta','Parda','Amarela','Indígena','Não declarada'].map(v=><Choice key={v} name="aluno-raca" value={v} checked={data.raca===v} onChange={radio('raca')}>{v}</Choice>)}</FieldGroup>{data.raca==='Indígena'&&<Input label="Código do povo indígena" required hint="Use 999 quando não houver a informação." value={data.povoIndigena} onChange={set('povoIndigena')} error={errors.povoIndigena}/>}<div className="form-grid"><Select label="Nacionalidade" required value={data.nacionalidade} onChange={set('nacionalidade')} error={errors.nacionalidade}><option>Brasileira</option><option>Brasileira — nascido no exterior ou naturalizado</option><option>Estrangeira</option></Select>{data.nacionalidade==='Estrangeira'&&<Input label="País da nacionalidade" required value={data.paisNacionalidade} onChange={set('paisNacionalidade')} error={errors.paisNacionalidade}/>}<Input label="UF de nascimento" maxLength="2" value={data.ufNascimento} onChange={set('ufNascimento')}/><Input label="Município de nascimento" value={data.municipioNascimento} onChange={set('municipioNascimento')}/></div></>}
    {step===2&&<><SectionTitle icon={<ShieldCheck/>} title="Necessidades e área residencial" subtitle="Recursos de acessibilidade e residência do aluno."/><FieldGroup label="Aluno(a) com deficiência, TEA, altas habilidades ou superdotação" required><Choice name="aluno-def" value="Sim" checked={data.deficiencia==='Sim'} onChange={radio('deficiencia')}>Sim</Choice><Choice name="aluno-def" value="Não" checked={data.deficiencia==='Não'} onChange={radio('deficiencia')}>Não</Choice></FieldGroup>{data.deficiencia==='Sim'&&<div><CheckboxGroup values={disabilityOptions} selected={data.tiposDeficiencia} onToggle={v=>toggle('tiposDeficiencia',v)}/>{errors.tiposDeficiencia&&<p className="field-error" role="alert">{errors.tiposDeficiencia}</p>}</div>}<FieldGroup label="Possui transtorno que impacta a aprendizagem?" required><Choice name="aluno-transtorno" value="Sim" checked={data.transtornoAprendizagem==='Sim'} onChange={radio('transtornoAprendizagem')}>Sim</Choice><Choice name="aluno-transtorno" value="Não" checked={data.transtornoAprendizagem==='Não'} onChange={radio('transtornoAprendizagem')}>Não</Choice></FieldGroup>{data.transtornoAprendizagem==='Sim'&&<div><CheckboxGroup values={disorderOptions} selected={data.tiposTranstorno} onToggle={v=>toggle('tiposTranstorno',v)}/>{errors.tiposTranstorno&&<p className="field-error" role="alert">{errors.tiposTranstorno}</p>}</div>}<FieldGroup label="Necessita de recursos em sala e em avaliações do Inep?" required><Choice name="aluno-recursos" value="Sim" checked={data.recursos==='Sim'} onChange={radio('recursos')}>Sim</Choice><Choice name="aluno-recursos" value="Não" checked={data.recursos==='Não'} onChange={radio('recursos')}>Não</Choice></FieldGroup>{data.recursos==='Sim'&&<div><CheckboxGroup values={resourceOptions} selected={data.tiposRecursos} onToggle={v=>toggle('tiposRecursos',v)}/>{errors.tiposRecursos&&<p className="field-error" role="alert">{errors.tiposRecursos}</p>}</div>}<Input label="Matrícula da certidão de nascimento (certidão nova)" value={data.certidao} onChange={set('certidao')}/><div className="form-grid"><Input label="País de residência" required value={data.paisResidencia} onChange={set('paisResidencia')} error={errors.paisResidencia}/><Input label="CEP" inputMode="numeric" value={data.cep} onChange={set('cep')} error={errors.cep}/><Input label="UF" required maxLength="2" value={data.ufResidencia} onChange={set('ufResidencia')} error={errors.ufResidencia}/><Input label="Município" required value={data.municipioResidencia} onChange={set('municipioResidencia')} error={errors.municipioResidencia}/></div><FieldGroup label="Zona de residência" required><Choice name="aluno-zona" value="Urbana" checked={data.zona==='Urbana'} onChange={radio('zona')}>Urbana</Choice><Choice name="aluno-zona" value="Rural" checked={data.zona==='Rural'} onChange={radio('zona')}>Rural</Choice></FieldGroup><Select label="Localização diferenciada" value={data.localizacao} onChange={set('localizacao')}><option>Não está em área de localização diferenciada</option><option>Área de assentamento</option><option>Comunidade quilombola</option><option>Terra indígena</option><option>Área de povos e comunidades tradicionais</option></Select></>}
    {step===3&&<><SectionTitle icon={<BookOpen/>} title="Dados de vínculo" subtitle="Turma, atendimento especializado e transporte escolar."/><div className="form-grid"><Input label="Nome da turma" required value={data.turma} onChange={set('turma')} error={errors.turma}/><Select label="Etapa do(a) aluno(a) na turma" required value={data.etapa} onChange={set('etapa')} error={errors.etapa}><option>Educação infantil — unificada</option><option>Creche</option><option>Pré-escola</option><option>Educação infantil e ensino fundamental — multietapa</option><option>Ensino fundamental em 9 anos — multi</option><option>Ensino fundamental em 9 anos — correção de fluxo</option><option>EJA — ensino fundamental multietapas</option><option>Curso técnico misto — concomitante</option><option>Curso técnico misto — subsequente</option></Select><Input label="Ano/etapa, quando aplicável" value={data.etapaAno} onChange={set('etapaAno')}/><Input label="Carga horária integralizada pelo aluno" type="number" min="0" value={data.cargaIntegralizada} onChange={set('cargaIntegralizada')}/></div><FieldGroup label="Tipo de atendimento educacional especializado (AEE)" hint="Selecione todos que se aplicam."><CheckboxGroup values={aeeOptions} selected={data.tiposAee} onToggle={v=>toggle('tiposAee',v)}/></FieldGroup><FieldGroup label="Atendimento educacional em regime hospitalar ou domiciliar"><Choice name="aluno-atendimento" value="Não recebe" checked={data.atendimento==='Não recebe'} onChange={radio('atendimento')}>Não recebe</Choice><Choice name="aluno-atendimento" value="Em domicílio" checked={data.atendimento==='Em domicílio'} onChange={radio('atendimento')}>Em domicílio</Choice><Choice name="aluno-atendimento" value="Em hospital" checked={data.atendimento==='Em hospital'} onChange={radio('atendimento')}>Em hospital</Choice></FieldGroup><FieldGroup label="Transporte escolar público"><Choice name="aluno-transporte" value="Utiliza" checked={data.transporte==='Utiliza'} onChange={radio('transporte')}>Utiliza</Choice><Choice name="aluno-transporte" value="Não utiliza" checked={data.transporte==='Não utiliza'} onChange={radio('transporte')}>Não utiliza</Choice></FieldGroup>{data.transporte==='Utiliza'&&<><FieldGroup label="Poder público responsável"><Choice name="aluno-responsavel" value="Municipal" checked={data.responsavelTransporte==='Municipal'} onChange={radio('responsavelTransporte')}>Municipal</Choice><Choice name="aluno-responsavel" value="Estadual" checked={data.responsavelTransporte==='Estadual'} onChange={radio('responsavelTransporte')}>Estadual</Choice></FieldGroup>{errors.responsavelTransporte&&<p className="field-error" role="alert">{errors.responsavelTransporte}</p>}<FieldGroup label="Tipo de veículo"><CheckboxGroup values={vehicleOptions} selected={data.veiculos} onToggle={v=>toggle('veiculos',v)}/></FieldGroup>{errors.veiculos&&<p className="field-error" role="alert">{errors.veiculos}</p>}</>}</>}
    {message&&<div className={message.startsWith('Aluno cadastrado')?'success-message':'error-message'} role="status">{message}</div>}<div className="form-actions"><button className="back-button" disabled={step===1||saving} onClick={()=>setStep(step-1)}><ArrowLeft size={18}/> Voltar</button><button className="primary-button" disabled={saving} onClick={next}>{saving?'Salvando...':step===3?'Cadastrar aluno':'Continuar'} {step===3?<CheckCircle2 size={18}/>:<ArrowRight size={18}/>}</button></div>
  </section>
}

function safeCsvValue(value){const raw=Array.isArray(value)?value.join(' | '):String(value??'');const safe=/^[=+\-@]/.test(raw)?`'${raw}`:raw;return `"${safe.replaceAll('"','""')}"`}
function downloadCsv(filename,headers,rows){const csv='\uFEFF'+[headers,...rows].map(row=>row.map(safeCsvValue).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
const professionalRow=r=>[r.id,r.nome,r.cpfRaw||onlyDigits(r.cpf),r.nascimento,r.email,onlyDigits(r.telefone),r.sexo,r.raca,r.cidade,r.uf,r.escolaridade,r.funcao,r.carga,r.vinculo,r.status,r.criadoEm]
const professionalHeaders=['Protocolo','Nome','CPF','Nascimento','E-mail','Celular','Sexo','Cor/raça','Município','UF','Escolaridade','Função','Carga','Vínculo','Status','Data do cadastro']
const studentHeaders=['Protocolo','Código escola','Código Inep','CPF','Nome','Nascimento','Sexo','Cor/raça','Povo indígena','Nacionalidade','Deficiência/TEA/AH','Tipos','Transtorno aprendizagem','Transtornos','Recursos','Recursos necessários','País residência','CEP','UF','Município','Zona','Localização','Turma','Etapa','Ano/etapa','Carga integralizada','AEE','Atendimento','Transporte','Responsável transporte','Veículos','Data do cadastro']
const studentRow=s=>[s.id,s.codigoEscola,s.identificacaoInep,s.cpf,s.nome,s.nascimento,s.sexo,s.raca,s.povoIndigena,s.nacionalidade,s.deficiencia,s.tiposDeficiencia,s.transtornoAprendizagem,s.tiposTranstorno,s.recursos,s.tiposRecursos,s.paisResidencia,s.cep,s.ufResidencia,s.municipioResidencia,s.zona,s.localizacao,s.turma,s.etapa,s.etapaAno,s.cargaIntegralizada,s.tiposAee,s.atendimento,s.transporte,s.responsavelTransporte,s.veiculos,s.criadoEm]

function Admin({ records, students, onSaveStudent, onLogout }) {
  const [view,setView]=useState('overview'),[search,setSearch]=useState(''),[filter,setFilter]=useState('Todos'),[selected,setSelected]=useState(null),[mobile,setMobile]=useState(false)
  const filtered=useMemo(()=>records.filter(r=>(filter==='Todos'||r.status===filter)&&(`${r.nome} ${r.cpfRaw||r.cpf} ${r.funcao}`.toLowerCase().includes(search.toLowerCase()))),[records,search,filter])
  const complete=records.filter(r=>r.status==='Completo').length, changeView=value=>{setView(value);setMobile(false);window.scrollTo(0,0)}
  const titles={overview:['Visão geral','Acompanhe os cadastros do NAPNE'],professionals:['Profissionais','Consulte os profissionais cadastrados'],reports:['Relatórios','Indicadores e planilhas para download'],forms:['Questionário do aluno','Preencha o formulário do Censo Escolar 2026']}
  const professionalTable=<section className="records-card"><div className="records-head"><div><h2>Profissionais cadastrados</h2><p>Selecione uma linha para consultar todos os dados.</p></div><div className="records-tools"><label><Search size={17}/><input aria-label="Buscar profissional" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar profissional..."/></label><select aria-label="Filtrar por status" value={filter} onChange={e=>setFilter(e.target.value)}><option>Todos</option><option>Completo</option><option>Pendente</option></select></div></div><div className="table-wrap"><table><thead><tr><th scope="col">PROFISSIONAL</th><th scope="col">FUNÇÃO</th><th scope="col">CARGA HORÁRIA</th><th scope="col">CADASTRO</th><th scope="col">STATUS</th><th scope="col"><span className="sr-only">Ações</span></th></tr></thead><tbody>{filtered.map(r=><tr key={r.id} onClick={()=>setSelected(r)}><td><div className="person-cell"><span>{initials(r.nome)}</span><div><b>{r.nome}</b><small>{r.cpfRaw||r.cpf}</small></div></div></td><td>{r.funcao}</td><td>{r.carga}</td><td>{formatDate(r.criadoEm)}</td><td><Status value={r.status}/></td><td><button className="row-button" aria-label={`Ver detalhes de ${r.nome}`} onClick={e=>{e.stopPropagation();setSelected(r)}}><MoreHorizontal/></button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="empty-state"><Search/><b>Nenhum cadastro encontrado</b><span>Tente usar outros termos de busca.</span></div>}</div><div className="table-footer">Mostrando <b>{filtered.length}</b> de <b>{records.length}</b> cadastros</div></section>
  return <div className="admin-shell"><a className="skip-link" href="#conteudo-admin">Ir para o conteúdo principal</a><aside className={mobile?'open':''}><div className="aside-head"><Logo light/><button onClick={()=>setMobile(false)} aria-label="Fechar menu"><X/></button></div><nav aria-label="Navegação administrativa"><span>PRINCIPAL</span><button className={view==='overview'?'active':''} onClick={()=>changeView('overview')}><LayoutDashboard/> Visão geral</button><button className={view==='professionals'?'active':''} onClick={()=>changeView('professionals')}><UsersRound/> Profissionais <i>{records.length}</i></button><button className={view==='reports'?'active':''} onClick={()=>changeView('reports')}><BarChart3/> Relatórios</button><span>GESTÃO</span><button className={view==='forms'?'active':''} onClick={()=>changeView('forms')}><FileText/> Questionário do aluno <i>{students.length}</i></button></nav><div className="admin-profile"><div>AS</div><span><b>Admin Sistema</b><small>Super administrador</small></span><button onClick={onLogout} title="Sair" aria-label="Sair"><LogOut size={18}/></button></div></aside><main className="admin-main" id="conteudo-admin"><header><button className="menu-button" onClick={()=>setMobile(true)} aria-label="Abrir menu"><Menu/></button><div><h1>{titles[view][0]}</h1><p>{titles[view][1]}</p></div>{view==='professionals'&&<button className="export-button" onClick={()=>downloadCsv('profissionais-napne-2026.csv',professionalHeaders,filtered.map(professionalRow))}><Download size={17}/> Baixar planilha</button>}</header>
    {view==='overview'&&<><section className="stats"><Stat icon={<UsersRound/>} label="Profissionais" value={records.length} note="cadastros" green/><Stat icon={<BookOpen/>} label="Alunos" value={students.length} note="questionários"/><Stat icon={<Clock3/>} label="Pendentes" value={records.length-complete} note="requer atenção" amber/></section>{professionalTable}</>}
    {view==='professionals'&&professionalTable}
    {view==='reports'&&<><section className="stats"><Stat icon={<UsersRound/>} label="Profissionais" value={records.length} note={`${complete} completos`} green/><Stat icon={<BookOpen/>} label="Alunos" value={students.length} note="Censo 2026"/><Stat icon={<ShieldCheck/>} label="Alunos com deficiência/TEA/AH" value={students.filter(s=>s.deficiencia==='Sim').length} note="com indicação" amber/></section><section className="report-grid"><article><FileText/><div><h2>Planilha de profissionais</h2><p>Dados completos e sem máscara de CPF, em CSV compatível com Excel e LibreOffice.</p></div><button className="primary-button" onClick={()=>downloadCsv('profissionais-napne-2026.csv',professionalHeaders,records.map(professionalRow))}><Download size={17}/> Baixar CSV</button></article><article><BookOpen/><div><h2>Planilha de alunos</h2><p>Respostas do questionário do aluno, incluindo recursos, AEE e transporte escolar.</p></div><button className="primary-button" disabled={!students.length} onClick={()=>downloadCsv('alunos-censo-escolar-2026.csv',studentHeaders,students.map(studentRow))}><Download size={17}/> Baixar CSV</button></article></section></>}
    {view==='forms'&&<><StudentQuestionnaire onSave={onSaveStudent}/>{students.length>0&&<section className="records-card student-list"><div className="records-head"><div><h2>Alunos cadastrados</h2><p>{students.length} questionário(s) registrado(s).</p></div><button className="export-button" onClick={()=>downloadCsv('alunos-censo-escolar-2026.csv',studentHeaders,students.map(studentRow))}><Download size={17}/> Baixar planilha</button></div><div className="table-wrap"><table><thead><tr><th scope="col">ALUNO(A)</th><th scope="col">TURMA</th><th scope="col">ESCOLA</th><th scope="col">CADASTRO</th></tr></thead><tbody>{students.map(s=><tr key={s.id}><td><b>{s.nome}</b><br/><small>{s.id}</small></td><td>{s.turma}</td><td>{s.codigoEscola}</td><td>{formatDate(s.criadoEm)}</td></tr>)}</tbody></table></div></section>}</>}
  </main>{selected&&<RecordDrawer record={selected} onClose={()=>setSelected(null)}/>}</div>
}
function Stat({icon,label,value,note,green,amber}) { return <div className={`stat ${green?'green':''} ${amber?'amber':''}`}><div className="stat-icon">{icon}</div><span><small>{label}</small><strong>{String(value).padStart(2,'0')}</strong><em>{note}</em></span></div> }
function Status({value}) { return <span className={`status ${value.toLowerCase()}`}><i></i>{value}</span> }
function initials(n){return n.split(' ').slice(0,2).map(x=>x[0]).join('')}
function formatDate(d){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d)).replace('.','')}

function RecordDrawer({record,onClose}) {
  const superiores = record.cursosSuperiores?.filter(item=>item.curso).map(item=>`${item.curso}${item.grau?` (${item.grau})`:''}${item.instituicao?` — ${item.instituicao}`:''}`).join('; ') || record.curso || '—'
  const formacoes = record.formacoesPedagogicas?.filter(item=>item.curso).map(item=>`${item.curso}${item.conclusao?` (${item.conclusao})`:''}`).join('; ') || '—'
  const posGraduacoes = record.posGraduacoes?.filter(item=>item.curso).map(item=>`${item.curso}${item.nivel?` (${item.nivel})`:''}`).join('; ') || record.pos || '—'
  const continuada = [...(record.cursos || []), ...(record.outrosCursos || []).filter(Boolean)].join(', ') || '—'
  const groups = [
    ['Dados pessoais', [['CPF',record.cpfRaw||record.cpf],['Data de nascimento',new Date(record.nascimento+'T12:00').toLocaleDateString('pt-BR')],['E-mail',record.email],['Telefone',record.telefone],['Sexo',record.sexo],['Cor/raça',record.raca],['Povo/tribo indígena',record.povoIndigena||'—'],['Filiação 1',record.filiacao1NaoDeclarada?'Não declarada':record.filiacao1||'—'],['Filiação 2',record.filiacao2NaoDeclarada?'Não declarada':record.filiacao2||'—']]],
    ['Formação', [['Escolaridade',record.escolaridade],['Cursos superiores',superiores],['Formação/complementação pedagógica',formacoes],['Pós-graduações',posGraduacoes],['Formação continuada',continuada]]],
    ['Atuação', [['Função',record.funcao],['Carga horária',record.carga],['Vínculo',record.vinculo],['Leciona no IFA',record.ifa||'Não'],['Área do IFA',record.areaIfa||'—'],['Leciona no IFTP',record.iftp||'Não'],['Área do IFTP',record.areaIftp||'—']]]
  ]
  return <div className="drawer-overlay" onClick={onClose}><aside className="drawer" onClick={e=>e.stopPropagation()}><header><div><span>DETALHES DO CADASTRO</span><h2>{record.nome}</h2><p>{record.id} • Enviado em {formatDate(record.criadoEm)}</p></div><button onClick={onClose}><X/></button></header><div className="drawer-profile"><div>{initials(record.nome)}</div><span><b>{record.funcao}</b><small>{record.cidade}, {record.uf}</small></span><Status value={record.status}/></div>{groups.map(([title,items])=><section key={title}><h3>{title}</h3><div className="detail-grid">{items.map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div></section>)}<button className="primary-button full" onClick={()=>window.print()}><Download size={17}/> Imprimir cadastro</button></aside></div>
}

export default function App() {
  const [route,setRoute]=useState(()=>location.hash.replace('#','')||'home')
  const [records,setRecords]=useState(initialRecords)
  const [students,setStudents]=useState([])
  const [lastRecord,setLastRecord]=useState(null)
  const [logged,setLogged]=useState(false)
  useEffect(()=>{const fn=()=>setRoute(location.hash.replace('#','')||'home');addEventListener('hashchange',fn);return()=>removeEventListener('hashchange',fn)},[])
  const go=r=>{location.hash=r;setRoute(r);window.scrollTo(0,0)}
  useEffect(()=>{fetch('/api/admin/session').then(r=>r.json()).then(x=>setLogged(x.authenticated)).catch(()=>{})},[])
  useEffect(()=>{if(logged)Promise.all([fetch('/api/admin/cadastros'),fetch('/api/admin/alunos')]).then(async([professionals,pupils])=>{if(!professionals.ok||!pupils.ok)throw new Error();setRecords(await professionals.json());setStudents(await pupils.json())}).catch(()=>setLogged(false))},[logged])
  const complete=async data=>{const response=await fetch('/api/cadastros',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Não foi possível enviar o cadastro.')}const record=await response.json();setRecords(current=>[record,...current]);setLastRecord(record);go('sucesso')}
  if(route==='cadastro')return <Registration onHome={()=>go('home')} onAdmin={()=>go('admin')} onComplete={complete}/>
  if(route==='sucesso'&&lastRecord)return <Success record={lastRecord} onHome={()=>go('home')}/>
  const saveStudent=async data=>{const response=await fetch('/api/admin/alunos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Não foi possível cadastrar o aluno.');setStudents(current=>[body,...current]);return body}
  if(route==='admin'){if(!logged)return <AdminLogin onBack={()=>go('home')} onLogin={()=>setLogged(true)}/>;return <Admin records={records} students={students} onSaveStudent={saveStudent} onLogout={async()=>{await fetch('/api/admin/logout',{method:'POST'});setLogged(false)}}/>}
  return <Landing onStart={()=>go('cadastro')} onAdmin={()=>go('admin')}/>
}
